import * as THREE from 'three';
import {territoryShell,SHIELD_RADIUS} from './shield-geometry.js';
import {ORBITAL,orbitBasis,orbitalPosition} from './orbital.js';
import {SHIELD} from './battle-engine.js';
export function createOrbitalVisuals({scene,features,spherical,glowTexture}){
 const root=new THREE.Group(),shields=[],satellites=[];scene.add(root);const texture=glowTexture();let identity='';
 const geometry=positions=>new THREE.BufferGeometry().setAttribute('position',new THREE.Float32BufferAttribute(positions,3));
 function clear(){root.traverse(o=>{o.geometry?.dispose();if(o.material)for(const m of [o.material].flat())m.dispose();});root.clear();shields.length=0;satellites.length=0;identity='';}
 function configure(teams,colors){clear();identity=teams.map(t=>t.id).join('/')+colors.join('/');teams.forEach((country,i)=>{
  const feature=features.find(f=>f.id===country.id);if(feature){const shell=territoryShell(feature),group=new THREE.Group();
   const material=new THREE.ShaderMaterial({uniforms:{tint:{value:new THREE.Color(colors[i])},strength:{value:1},time:{value:0}},transparent:true,depthWrite:false,side:THREE.DoubleSide,blending:THREE.AdditiveBlending,vertexShader:'varying vec3 p;varying vec3 n;varying vec3 v;void main(){p=position;n=normalize(normalMatrix*normalize(position));vec4 pos=modelViewMatrix*vec4(position,1.);v=normalize(-pos.xyz);gl_Position=projectionMatrix*pos;}',fragmentShader:'uniform vec3 tint;uniform float strength;uniform float time;varying vec3 p;varying vec3 n;varying vec3 v;void main(){float lon=atan(p.x,p.z),lat=asin(normalize(p).y);vec2 grid=abs(fract(vec2(lon,lat)*55.)-.5);float lines=1.-smoothstep(.025,.065,min(grid.x,grid.y));float rim=pow(1.-abs(dot(normalize(n),normalize(v))),2.);float scan=pow(.5+.5*sin(lat*18.-time*1.3),12.);float opacity=(.055+lines*.12+rim*.12+scan*.035)*strength;gl_FragColor=vec4(tint,opacity);}'});
   const cap=new THREE.Mesh(geometry(shell.top),material),wall=new THREE.Mesh(geometry(shell.walls),new THREE.MeshBasicMaterial({color:colors[i],transparent:true,opacity:.12,side:THREE.DoubleSide,depthWrite:false,blending:THREE.AdditiveBlending})),outline=new THREE.LineSegments(geometry(shell.border),new THREE.LineBasicMaterial({color:colors[i],transparent:true,opacity:.8,depthWrite:false,blending:THREE.AdditiveBlending}));group.add(cap,wall,outline);root.add(group);shields.push({group,cap,wall,outline,index:i});
  }
  const model=new THREE.Group();model.add(new THREE.Mesh(new THREE.BoxGeometry(.065,.075,.1),new THREE.MeshBasicMaterial({color:0xd3e3ed})));
  for(const sign of [-1,1]){const arm=new THREE.Mesh(new THREE.BoxGeometry(.12,.012,.012),new THREE.MeshBasicMaterial({color:0xacc5d2}));arm.position.x=sign*.08;model.add(arm);const panel=new THREE.Mesh(new THREE.BoxGeometry(.15,.012,.14),new THREE.MeshBasicMaterial({color:0x173963}));panel.position.x=sign*.16;model.add(panel);const grid=new THREE.LineSegments(new THREE.EdgesGeometry(panel.geometry),new THREE.LineBasicMaterial({color:colors[i],transparent:true,opacity:.85}));grid.position.copy(panel.position);model.add(grid);for(let k=-1;k<=1;k++){const stripe=new THREE.Mesh(new THREE.BoxGeometry(.003,.014,.14),new THREE.MeshBasicMaterial({color:0x6d94be}));stripe.position.set(sign*.16+k*.04,0,0);model.add(stripe);}}
  const emitter=new THREE.Mesh(new THREE.ConeGeometry(.025,.07,10),new THREE.MeshBasicMaterial({color:0xff5163}));emitter.position.y=-.06;emitter.rotation.z=Math.PI;model.add(emitter);
  const beacon=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,color:colors[i],blending:THREE.AdditiveBlending,depthWrite:false}));beacon.scale.setScalar(.12);model.add(beacon);root.add(model);
  const beam=new THREE.Group();const core=new THREE.Mesh(new THREE.CylinderGeometry(.006,.009,1,8),new THREE.MeshBasicMaterial({color:0xff3048,transparent:true,opacity:.95,depthWrite:false,blending:THREE.AdditiveBlending})),halo=new THREE.Mesh(new THREE.CylinderGeometry(.025,.035,1,10),new THREE.MeshBasicMaterial({color:0xff1537,transparent:true,opacity:.16,depthWrite:false,blending:THREE.AdditiveBlending}));beam.add(core,halo);beam.visible=false;root.add(beam);
  const impact=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,color:0xff2547,blending:THREE.AdditiveBlending,depthWrite:false}));impact.scale.setScalar(.2);impact.visible=false;root.add(impact);
  const orbit=new THREE.Line(new THREE.BufferGeometry(),new THREE.LineBasicMaterial({color:colors[i],transparent:true,opacity:.12,depthWrite:false}));root.add(orbit);satellites.push({model,beam,impact,orbit,beacon,route:''});
 });}
 function update(state,teams,colors){if(identity!==teams.map(t=>t.id).join('/')+colors.join('/'))configure(teams,colors);
  for(const s of shields){const f=state.fighters[s.index];if(!f)continue;const ratio=f.shield/SHIELD.capacity;s.group.visible=f.hp>0&&ratio>.001;s.cap.material.uniforms.strength.value=.25+.75*ratio;s.cap.material.uniforms.time.value=state.time;s.wall.material.opacity=.035+.14*ratio;s.outline.material.opacity=.2+.7*ratio;}
  state.satellites.forEach((s,i)=>{const visual=satellites[i];if(!visual)return;const active=state.orbitalEnabled&&state.fighters[i].hp>0;visual.model.visible=active;visual.orbit.visible=active;visual.beam.visible=active&&s.phase==='firing'&&['running','paused'].includes(state.status);visual.impact.visible=visual.beam.visible;
   if(!active)return;visual.beacon.material.color.set(s.target!==null&&state.fighters[s.target].jamUntil>state.time?0xffd06b:colors[i]);const position=new THREE.Vector3(...orbitalPosition(s));visual.model.position.copy(position);visual.model.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),position.clone().normalize());visual.model.rotateY(state.time*.15);
   const key=JSON.stringify([s.origin,s.destination]);if(visual.route!==key){visual.route=key;const basis=orbitBasis(s.origin,s.destination),points=[];for(let k=0;k<=128;k++){const angle=k/128*Math.PI*2;points.push(new THREE.Vector3(...basis.a.map((x,j)=>(x*Math.cos(angle)+basis.tangent[j]*Math.sin(angle))*ORBITAL.radius)));}visual.orbit.geometry.dispose();visual.orbit.geometry=new THREE.BufferGeometry().setFromPoints(points);}
   if(visual.beam.visible){const target=state.fighters[s.target],end=spherical(s.destination.lat,s.destination.lon,target.shield>0?SHIELD_RADIUS+.003:2.032),direction=end.clone().sub(position);visual.beam.position.copy(position).add(end).multiplyScalar(.5);visual.beam.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),direction.clone().normalize());visual.beam.scale.set(1+Math.sin(state.time*12)*.08,direction.length(),1);visual.impact.material.color.set(s.decoy?0xffc866:0xff2547);visual.impact.position.copy(end);visual.impact.scale.setScalar(.17+Math.sin(state.time*8)*.025);}
  });
 }
 return {update,clear,configure};
}
